(26, 1, '2025-01-31 06:44:22', '0000-00-00 00:00:00', '<img src=\"http://localhost/wordpress/wp-content/plugins/elementor/assets/images/placeholder.png\" title=\"\" alt=\"\" loading=\"lazy\" />															\n							<ul>\n							<li>\n										123-456-7890\n									</li>\n						</ul>\n					<h1>Contact Us</h1>				\n		<p>We would love to hear from you.<br />Feel free to reach out using the below details.</p>		\n															<img width=\"920\" height=\"657\" src=\"http://localhost/wordpress/wp-content/uploads/2025/01/About-2-Hero.jpg\" alt=\"\" />															\n															<img width=\"853\" height=\"430\" src=\"http://localhost/wordpress/wp-content/uploads/2025/01/Image-Contact-1.jpg\" alt=\"\" />															\n							<ul>\n							<li>\n										<b>Address:</b> 123 Main Street, New York, NY 10001\n									</li>\n								<li>\n										<b>Hours:</b> Mon-Fri 9:00AM - 5:00PM\n									</li>\n								<li>\n										<b>Phone:</b> 123-456-7890\n									</li>\n								<li>\n										<b>Email:</b> contact@mysite.com\n									</li>\n						</ul>\n			<iframe loading=\"lazy\"\n					src=\"https://maps.google.com/maps?q=Broadway%20%26%2C%20Chambers%20St%2C%20New%20York%2C%20NY%2010007%2C%20United%20States&#038;t=m&#038;z=17&#038;output=embed&#038;iwloc=near\"\n					title=\"Broadway &amp;, Chambers St, New York, NY 10007, United States\"\n					aria-label=\"Broadway &amp;, Chambers St, New York, NY 10007, United States\"\n			></iframe>\n					<h2>Visit Us</h2>				\n									<h4>\n							Address:						\n					</h4>\n									<p>\n						123 Main Street\nNew York, NY 10001					</p>\n					<p>© All Rights Reserved.</p>', 'Elementor #26', '', 'draft', 'closed', 'closed', '', '', '', '', '2025-01-31 06:44:22', '2025-01-31 06:44:22', '', 0, 'http://localhost/wordpress/?page_id=26', 0, 'page', '', 0),
