CREATE TABLE `productions` (
  `production_id` int(11) NOT NULL,
  `title` varchar(100) NOT NULL,
  `type` enum('Play','Musical','Concert') NOT NULL,
  `description` text DEFAULT NULL,
  `duration` int(11) DEFAULT NULL,
  `status` enum('active','inactive','completed') DEFAULT 'active',
  `image_path` varchar(255) DEFAULT NULL,
  `image_thumbnail` varchar(255) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `created_by` int(11) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Dumping data for table `productions`
--

INSERT INTO `productions` (`production_id`, `title`, `type`, `description`, `duration`, `status`, `image_path`, `image_thumbnail`, `created_at`, `created_by`) VALUES
(1, 'PPO Concert III - FANTASY', 'Concert', 'Celebrate the Philippine Philharmonic Orchestra’s milestone 40th season with \"Forte!,\" a dynamic series of seven concerts showcasing a blend of classical masterpieces and contemporary works. The season kicks off with a vibrant opening, \"Fiesta!,\" and spans through evocative themes like \"Triumph,\" \"Fantasy,\" \"Europa,\" and \"Hope,\" culminating in a powerful \"Finale.\" Featuring world-class soloists and conductors, this season promises to be an unforgettable musical journey, highlighting both beloved compositions and innovative premieres under the baton of PPO\'s Music Director and Principal Conductor, Maestro Grzegorz Nowak.', 59, 'active', 'uploads/productions/675001ebd75d2_1733296619.jpg', 'uploads/productions/thumbnails/675001ebd75d2_1733296619.jpg', '2024-12-03 08:07:20', NULL),
(2, 'GOMBURZA', 'Play', 'An American Musical by Lin-Manuel Miranda', 165, 'active', 'uploads/productions/674fc8a8f28c2_1733281960.jpg', 'uploads/productions/thumbnails/674fc8a8f28c2_1733281960.jpg', '2024-12-03 08:07:20', NULL),
(3, 'Oh Christmass Tree', 'Musical', 'Disney\'s beloved musical adaptation', 150, 'active', 'uploads/productions/674fc7e0a93ae_1733281760.jpg', 'uploads/productions/thumbnails/674fc7e0a93ae_1733281760.jpg', '2024-12-03 08:07:20', NULL),
(4, 'Romeo and Juliet', 'Musical', 'Shakespeare\'s timeless love story', 180, 'active', 'uploads/productions/674fe4caa21b9_1733289162.jpg', 'uploads/productions/thumbnails/674fe4caa21b9_1733289162.jpg', '2024-12-03 08:07:20', NULL),
(5, 'Peter Pan', 'Play', 'A voyage to Neverland that transcends cultures, rekindled with a spark of Filipino wonder. This production is imbued with the values of kinship and the youthful spirit of adventure that are hallmark traits of our islands. Its a reminder of the timeless joy found in stories shared across generations in the Philippines, where family and community are the center of our universe.', 60, 'active', 'uploads/productions/674fc684da1ce_1733281412.jpg', 'uploads/productions/thumbnails/674fc684da1ce_1733281412.jpg', '2024-12-04 03:03:32', 1),
(6, 'Snow White By Lisa Macuja Elizalde', 'Musical', 'Lisa Macuja Elizalde’s beloved version of SNOW WHITE returns to the live stage in Ballet Manila’s Holiday Cheer Series 2024 edition! The prima ballerina’s dance interepretation of this classic fairy tale puts together elements from the Borthers Grimm and Disney versions – and through magical storytelling, stunning staging, stellar dancing results ballet that will surely evoke happiness and delight!', 59, 'active', 'uploads/productions/674ff717089d8_1733293847.jpg', 'uploads/productions/thumbnails/674ff717089d8_1733293847.jpg', '2024-12-04 06:30:47', 1),
(7, 'Christmas Ballets', 'Play', 'The season of Christmas is always more magical with music, dance, and CHRISTMAS BALLETS for the whole family to enjoy!\r\n\r\nA holiday collaboration between Steps Dance Studio, BPI Wealth, and Samsung Performing Arts Theater brings you a captivating two-act ballet this Christmas season, from December 13 to 15.', 59, 'active', 'uploads/productions/67529db2b72dc_1733467570.jpg', 'uploads/productions/thumbnails/67529db2b72dc_1733467570.jpg', '2024-12-06 06:46:10', 1),
(8, 'dfgsadfsdfsd', 'Musical', 'dgfsdfhsdfgsdfgxvzad', 60, 'active', 'uploads/productions/6752a5af8684b_1733469615.jpg', 'uploads/productions/thumbnails/6752a5af8684b_1733469615.jpg', '2024-12-06 07:20:15', 1),
(9, 'sgsdf', 'Play', 'fasdgasdgasdf', 56, 'active', 'uploads/productions/6752b458acd60_1733473368.jpg', 'uploads/productions/thumbnails/6752b458acd60_1733473368.jpg', '2024-12-06 08:22:48', 1),
